// 剪切板历史模块(D012): 后台监控 NSPasteboard.general.changeCount → SQLite 本地存储 → ⌥V 呼出搜索面板 → 写回剪切板。
// 隐私基线: 跳过 org.nspasteboard.ConcealedType/TransientType/AutoGeneratedType, 密码管理器前台不记录,
// 敏感内容(身份证/银行卡/密钥)短 TTL 自动过期。纯本地, 无网络, 无系统权限。

import SwiftUI
import AppKit
import SQLite3
import CryptoKit

// MARK: - 通知名
extension Notification.Name {
    static let clipStoreDidChange = Notification.Name("clipStoreDidChange")
    static let clipWriteBackDone = Notification.Name("clipWriteBackDone")
    static let clipDismiss = Notification.Name("clipDismiss")
}

// MARK: - 模型
enum ClipKind: String {
    case text, url, json, code, color, image, file

    var icon: String {
        switch self {
        case .text: return "text.alignleft"
        case .url: return "link"
        case .json: return "curlybraces"
        case .code: return "chevron.left.forwardslash.chevron.right"
        case .color: return "paintpalette"
        case .image: return "photo"
        case .file: return "doc"
        }
    }

    var label: String {
        switch self {
        case .text: return "文本"
        case .url: return "链接"
        case .json: return "JSON"
        case .code: return "代码"
        case .color: return "颜色"
        case .image: return "图片"
        case .file: return "文件"
        }
    }
}

struct Clip: Identifiable {
    let id: Int64
    let hash: String
    let kind: ClipKind
    let content: String?
    let imageData: Data?
    let thumbData: Data?
    let fileURLs: [URL]
    let sourceApp: String?
    let pinned: Bool
    let createdAt: Date
    let sensitive: Bool
    var expiresAt: Date? = nil
    var isExpired: Bool { expiresAt.map { $0 <= Date() } ?? false }

    var preview: String {
        switch kind {
        case .image: return "图片"
        case .file: return fileURLs.map { $0.lastPathComponent }.joined(separator: ", ")
        default: return content ?? ""
        }
    }

    var isMonospaced: Bool { kind == .code || kind == .json }
}

struct ClipRecord {
    let hash: String
    let kind: ClipKind
    let content: String?
    let imageData: Data?
    let thumbData: Data?
    let fileURLs: [URL]
    let sourceApp: String?
    let sensitive: Bool
    let expiresAt: Date?
}

// MARK: - 设置
enum ClipSettings {
    static let historyLimitKey = "clip.historyLimit"
    static let recordImagesKey = "clip.recordImages"
    static let sensitiveTTLKey = "clip.sensitiveTTLMinutes"
    static let floatOnWriteBackKey = "clip.floatOnWriteBack"
    static let defaultHistoryLimit = 500

    static var historyLimit: Int {
        let v = UserDefaults.standard.object(forKey: historyLimitKey) as? Int ?? 0
        return v > 0 ? v : defaultHistoryLimit
    }
    static var recordImages: Bool {
        UserDefaults.standard.object(forKey: recordImagesKey) as? Bool ?? true
    }
    static var sensitiveTTLMinutes: Int {
        let v = UserDefaults.standard.object(forKey: sensitiveTTLKey) as? Int ?? 0
        return v > 0 ? v : 30
    }
    /// 写回(Enter/双击)后是否把条目浮到列表最上面, 默认开
    static var floatOnWriteBack: Bool {
        UserDefaults.standard.object(forKey: floatOnWriteBackKey) as? Bool ?? true
    }
}

// MARK: - 敏感内容识别
enum SensitiveDetector {
    private static let keyMarkers = ["AKIA", "ghp_", "gho_", "xoxb-", "xoxp-"]

    static func isSensitive(_ rawText: String) -> Bool {
        let text = rawText
        for marker in keyMarkers where text.contains(marker) { return true }
        if text.contains("-----BEGIN"), text.contains("PRIVATE KEY-----") { return true }
        if let regex = try? NSRegularExpression(pattern: "sk-[A-Za-z0-9_-]{20,}"),
           regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) != nil { return true }
        if containsIDCard(text) { return true }
        if containsBankCard(text) { return true }
        return false
    }

    /// 大陆 18 位身份证(含生日段合法性)
    private static func containsIDCard(_ text: String) -> Bool {
        let pattern = "\\d{6}(19|20)\\d{2}(0[1-9]|1[0-2])(0[1-9]|[12]\\d|3[01])\\d{3}[\\dXx]"
        guard let regex = try? NSRegularExpression(pattern: pattern) else { return false }
        return regex.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) != nil
    }

    /// 银行卡 16-19 位 + Luhn, 容忍空格/短横分隔
    private static func containsBankCard(_ text: String) -> Bool {
        let compact = text.replacingOccurrences(of: " ", with: "")
                          .replacingOccurrences(of: "-", with: "")
        guard let regex = try? NSRegularExpression(pattern: "\\d{16,19}") else { return false }
        let ns = compact as NSString
        var found = false
        regex.enumerateMatches(in: compact, options: [], range: NSRange(location: 0, length: ns.length)) { m, _, stop in
            guard let r = m?.range else { return }
            if luhn(ns.substring(with: r)) { found = true; stop.pointee = true }
        }
        return found
    }

    private static func luhn(_ digits: String) -> Bool {
        let values = digits.compactMap { $0.wholeNumberValue }
        guard values.count == digits.count, values.count >= 16 else { return false }
        var sum = 0
        for (idx, digit) in values.reversed().enumerated() {
            if idx % 2 == 1 {
                let doubled = digit * 2
                sum += doubled > 9 ? doubled - 9 : doubled
            } else {
                sum += digit
            }
        }
        return sum % 10 == 0
    }
}

// MARK: - 拼音索引
enum Pinyin {
    /// 返回(全拼小写, 首字母串)。只索引前 400 字符, 控制成本。
    static func of(_ text: String) -> (full: String, initials: String) {
        let source = String(text.prefix(400))
        let mutable = NSMutableString(string: source) as CFMutableString
        CFStringTransform(mutable, nil, kCFStringTransformMandarinLatin, false)
        CFStringTransform(mutable, nil, kCFStringTransformStripDiacritics, false)
        let full = (mutable as String).lowercased()
        let initials = full.split(separator: " ")
            .compactMap { token in token.first(where: { $0.isLetter }).map(String.init) }
            .joined()
        return (full, initials)
    }
}

// MARK: - SQLite 存储
final class ClipboardStore {
    static let shared = ClipboardStore()

    private var db: OpaquePointer?
    private let queue = DispatchQueue(label: "com.zz.dboard.clipboard.store")
    private let SQLITE_TRANSIENT = unsafeBitCast(-1, to: sqlite3_destructor_type.self)

    init(url: URL? = nil) {
        let dir = url?.deletingLastPathComponent() ?? FileManager.default.homeDirectoryForCurrentUser
            .appendingPathComponent("Library/Application Support/DBoard", isDirectory: true)
        try? FileManager.default.createDirectory(at: dir, withIntermediateDirectories: true)
        let path = url?.path ?? dir.appendingPathComponent("clipboard.sqlite").path
        if sqlite3_open(path, &db) != SQLITE_OK {
            NSLog("ClipboardStore: 无法打开 \(path)")
            db = nil
            return
        }
        exec("""
            CREATE TABLE IF NOT EXISTS clips (
              id INTEGER PRIMARY KEY AUTOINCREMENT,
              hash TEXT UNIQUE NOT NULL,
              kind TEXT NOT NULL,
              content TEXT,
              image_data BLOB,
              thumb_data BLOB,
              file_urls TEXT,
              source_app TEXT,
              pinned INTEGER NOT NULL DEFAULT 0,
              created_at REAL NOT NULL,
              sensitive INTEGER NOT NULL DEFAULT 0,
              expires_at REAL
            );
            CREATE INDEX IF NOT EXISTS idx_clips_created ON clips(created_at DESC);
            """)
        purgeLocked()
    }

    deinit { if let db { sqlite3_close(db) } }

    // MARK: 写入

    func insert(_ record: ClipRecord) {
        queue.sync { insertLocked(record) }
        NotificationCenter.default.post(name: .clipStoreDidChange, object: nil)
    }

    private func insertLocked(_ record: ClipRecord) {
        guard let db else { return }
        let now = Date().timeIntervalSince1970
        // 去重: 已存在则刷新时间浮顶(敏感标记一并刷新)
        var sel: OpaquePointer?
        if sqlite3_prepare_v2(db, "SELECT id FROM clips WHERE hash = ?", -1, &sel, nil) == SQLITE_OK {
            bindText(sel, 1, record.hash)
            if sqlite3_step(sel) == SQLITE_ROW {
                let id = sqlite3_column_int64(sel, 0)
                sqlite3_finalize(sel)
                var up: OpaquePointer?
                if sqlite3_prepare_v2(db, "UPDATE clips SET created_at = ?, sensitive = ?, expires_at = ? WHERE id = ?", -1, &up, nil) == SQLITE_OK {
                    sqlite3_bind_double(up, 1, now)
                    sqlite3_bind_int(up, 2, record.sensitive ? 1 : 0)
                    if let exp = record.expiresAt { sqlite3_bind_double(up, 3, exp.timeIntervalSince1970) } else { sqlite3_bind_null(up, 3) }
                    sqlite3_bind_int64(up, 4, id)
                    sqlite3_step(up)
                    sqlite3_finalize(up)
                }
                purgeLocked()
                return
            }
            sqlite3_finalize(sel)
        }
        var ins: OpaquePointer?
        let sql = """
            INSERT INTO clips (hash, kind, content, image_data, thumb_data, file_urls, source_app, pinned, created_at, sensitive, expires_at)
            VALUES (?, ?, ?, ?, ?, ?, ?, 0, ?, ?, ?)
            """
        guard sqlite3_prepare_v2(db, sql, -1, &ins, nil) == SQLITE_OK else { return }
        defer { sqlite3_finalize(ins) }
        bindText(ins, 1, record.hash)
        bindText(ins, 2, record.kind.rawValue)
        if let c = record.content { bindText(ins, 3, c) } else { sqlite3_bind_null(ins, 3) }
        if let d = record.imageData { bindBlob(ins, 4, d) } else { sqlite3_bind_null(ins, 4) }
        if let d = record.thumbData { bindBlob(ins, 5, d) } else { sqlite3_bind_null(ins, 5) }
        let urlsJSON = (try? JSONSerialization.data(withJSONObject: record.fileURLs.map { $0.absoluteString }))
            .flatMap { String(data: $0, encoding: .utf8) }
        if let u = urlsJSON { bindText(ins, 6, u) } else { sqlite3_bind_null(ins, 6) }
        if let s = record.sourceApp { bindText(ins, 7, s) } else { sqlite3_bind_null(ins, 7) }
        sqlite3_bind_double(ins, 8, now)
        sqlite3_bind_int(ins, 9, record.sensitive ? 1 : 0)
        if let exp = record.expiresAt { sqlite3_bind_double(ins, 10, exp.timeIntervalSince1970) } else { sqlite3_bind_null(ins, 10) }
        sqlite3_step(ins)
        purgeLocked()
    }

    // MARK: 读取

    func loadAll() -> [Clip] {
        queue.sync {
            guard let db else { return [] }
            var out: [Clip] = []
            var stmt: OpaquePointer?
            let sql = """
                SELECT id, hash, kind, content, image_data, thumb_data, file_urls, source_app, pinned, created_at, sensitive, expires_at
                FROM clips WHERE expires_at IS NULL OR expires_at > \(Date().timeIntervalSince1970)
                ORDER BY pinned DESC, created_at DESC LIMIT 3000
                """
            guard sqlite3_prepare_v2(db, sql, -1, &stmt, nil) == SQLITE_OK else { return [] }
            defer { sqlite3_finalize(stmt) }
            while sqlite3_step(stmt) == SQLITE_ROW {
                var urls: [URL] = []
                if let j = colText(stmt, 6),
                   let arr = (try? JSONSerialization.jsonObject(with: Data(j.utf8))) as? [String] {
                    urls = arr.compactMap { URL(string: $0) }
                }
                out.append(Clip(
                    id: sqlite3_column_int64(stmt, 0),
                    hash: colText(stmt, 1) ?? "",
                    kind: ClipKind(rawValue: colText(stmt, 2) ?? "text") ?? .text,
                    content: colText(stmt, 3),
                    imageData: colBlob(stmt, 4),
                    thumbData: colBlob(stmt, 5),
                    fileURLs: urls,
                    sourceApp: colText(stmt, 7),
                    pinned: sqlite3_column_int(stmt, 8) != 0,
                    createdAt: Date(timeIntervalSince1970: sqlite3_column_double(stmt, 9)),
                    sensitive: sqlite3_column_int(stmt, 10) != 0,
                    expiresAt: sqlite3_column_type(stmt, 11) == SQLITE_NULL ? nil : Date(timeIntervalSince1970: sqlite3_column_double(stmt, 11))))
            }
            return out
        }
    }

    // MARK: 修改/清理

    func setPinned(id: Int64, pinned: Bool) {
        queue.sync {
            guard let db else { return }
            var stmt: OpaquePointer?
            guard sqlite3_prepare_v2(db, "UPDATE clips SET pinned = ? WHERE id = ?", -1, &stmt, nil) == SQLITE_OK else { return }
            defer { sqlite3_finalize(stmt) }
            sqlite3_bind_int(stmt, 1, pinned ? 1 : 0)
            sqlite3_bind_int64(stmt, 2, id)
            sqlite3_step(stmt)
        }
        NotificationCenter.default.post(name: .clipStoreDidChange, object: nil)
    }

    func delete(id: Int64) {
        queue.sync {
            guard let db else { return }
            var stmt: OpaquePointer?
            guard sqlite3_prepare_v2(db, "DELETE FROM clips WHERE id = ?", -1, &stmt, nil) == SQLITE_OK else { return }
            defer { sqlite3_finalize(stmt) }
            sqlite3_bind_int64(stmt, 1, id)
            sqlite3_step(stmt)
        }
        NotificationCenter.default.post(name: .clipStoreDidChange, object: nil)
    }

    /// 刷新时间戳使条目浮到列表最上面（写回后置顶用）
    func touch(id: Int64) {
        queue.sync {
            guard let db else { return }
            var stmt: OpaquePointer?
            guard sqlite3_prepare_v2(db, "UPDATE clips SET created_at = ? WHERE id = ?", -1, &stmt, nil) == SQLITE_OK else { return }
            defer { sqlite3_finalize(stmt) }
            sqlite3_bind_double(stmt, 1, Date().timeIntervalSince1970)
            sqlite3_bind_int64(stmt, 2, id)
            sqlite3_step(stmt)
        }
        NotificationCenter.default.post(name: .clipStoreDidChange, object: nil)
    }

    func purge() {
        queue.sync { purgeLocked() }
        NotificationCenter.default.post(name: .clipStoreDidChange, object: nil)
    }

    /// 过期敏感条目删除 + 非置顶超出上限的旧条目删除
    private func purgeLocked() {
        guard let db else { return }
        let now = Date().timeIntervalSince1970
        exec("DELETE FROM clips WHERE expires_at IS NOT NULL AND expires_at <= \(now)")
        var stmt: OpaquePointer?
        guard sqlite3_prepare_v2(db,
            "DELETE FROM clips WHERE pinned = 0 AND id NOT IN (SELECT id FROM clips ORDER BY created_at DESC LIMIT ?)",
            -1, &stmt, nil) == SQLITE_OK else { return }
        defer { sqlite3_finalize(stmt) }
        sqlite3_bind_int(stmt, 1, Int32(ClipSettings.historyLimit))
        sqlite3_step(stmt)
    }

    // MARK: SQLite helpers

    private func exec(_ sql: String) {
        sqlite3_exec(db, sql, nil, nil, nil)
    }

    private func bindText(_ stmt: OpaquePointer?, _ idx: Int32, _ value: String) {
        sqlite3_bind_text(stmt, idx, value, -1, SQLITE_TRANSIENT)
    }

    private func bindBlob(_ stmt: OpaquePointer?, _ idx: Int32, _ data: Data) {
        _ = data.withUnsafeBytes { raw in
            sqlite3_bind_blob(stmt, idx, raw.baseAddress, Int32(data.count), SQLITE_TRANSIENT)
        }
    }

    private func colText(_ stmt: OpaquePointer?, _ idx: Int32) -> String? {
        guard let c = sqlite3_column_text(stmt, idx) else { return nil }
        return String(cString: c)
    }

    private func colBlob(_ stmt: OpaquePointer?, _ idx: Int32) -> Data? {
        guard let bytes = sqlite3_column_blob(stmt, idx) else { return nil }
        return Data(bytes: bytes, count: Int(sqlite3_column_bytes(stmt, idx)))
    }
}

// MARK: - 后台监控
final class ClipboardMonitor {
    static let shared = ClipboardMonitor()

    private var timer: Timer?
    private var lastChangeCount: Int = 0
    private let workQueue = DispatchQueue(label: "com.zz.dboard.clipboard.capture")

    /// 密码管理器 bundle id: 前台是它们时复制的内容一律不记录
    private let passwordManagerBundles: Set<String> = [
        "com.1password.1password", "com.agilebits.onepassword7", "com.agilebits.onepassword8",
        "com.bitwarden.desktop", "com.lastpass.LastPass", "com.dashlane.Dashlane",
        "com.apple.keychainaccess"
    ]

    /// 常规排除类型(密码管理器/剪贴板增强工具约定的不记录标记)
    private let excludedTypes: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType"
    ]

    private init() {}

    func start() {
        guard timer == nil else { return }
        lastChangeCount = NSPasteboard.general.changeCount
        let t = Timer(timeInterval: 0.5, repeats: true) { [weak self] _ in self?.poll() }
        RunLoop.main.add(t, forMode: .common)
        timer = t
    }

    /// DBoard 自己写剪切板后调用, 避免自己的回填/复制按钮进入历史
    func noteSelfWrite() {
        lastChangeCount = NSPasteboard.general.changeCount
    }

    private func poll() {
        let pb = NSPasteboard.general
        let cc = pb.changeCount
        guard cc != lastChangeCount else { return }
        lastChangeCount = cc
        // frontmostApplication 必须主线程取
        let frontBundle = NSWorkspace.shared.frontmostApplication?.bundleIdentifier
        workQueue.async { [weak self] in
            self?.capture(pasteboard: pb, frontBundle: frontBundle)
        }
    }

    private func capture(pasteboard pb: NSPasteboard, frontBundle: String?) {
        if let bundle = frontBundle {
            if bundle == Bundle.main.bundleIdentifier { return }   // DBoard 内部复制不进历史
            if passwordManagerBundles.contains(bundle) { return }
        }
        guard let items = pb.pasteboardItems, !items.isEmpty else { return }
        for item in items where item.types.contains(where: { excludedTypes.contains($0.rawValue) }) {
            return
        }

        // 文件: 聚合所有 item 的 fileURL(Finder 多选复制)
        let fileURLs = items.compactMap { $0.string(forType: .fileURL) }.compactMap { URL(string: $0) }
        if !fileURLs.isEmpty {
            ClipboardStore.shared.insert(ClipRecord(
                hash: sha256("file:" + fileURLs.map { $0.absoluteString }.joined(separator: "\n")),
                kind: .file,
                content: fileURLs.map { $0.lastPathComponent }.joined(separator: ", "),
                imageData: nil, thumbData: nil, fileURLs: fileURLs,
                sourceApp: frontBundle, sensitive: false, expiresAt: nil))
            return
        }

        guard let item = items.first else { return }

        // 图片(png/tiff/jpeg/heic 都收, 统一转 PNG 存)
        let jpegType = NSPasteboard.PasteboardType("public.jpeg")
        let heicType = NSPasteboard.PasteboardType("public.heic")
        if ClipSettings.recordImages,
           let raw = item.data(forType: .png) ?? item.data(forType: .tiff)
                ?? item.data(forType: jpegType) ?? item.data(forType: heicType),
           let record = captureImage(data: raw, sourceApp: frontBundle) {
            ClipboardStore.shared.insert(record)
            return
        }

        // 文本
        guard var text = item.string(forType: .string) else { return }
        text = text.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !text.isEmpty else { return }
        if text.count > 200_000 { text = String(text.prefix(200_000)) }

        let sensitive = SensitiveDetector.isSensitive(text)
        ClipboardStore.shared.insert(ClipRecord(
            hash: sha256("text:" + text),
            kind: classify(text),
            content: text, imageData: nil, thumbData: nil, fileURLs: [],
            sourceApp: frontBundle,
            sensitive: sensitive,
            expiresAt: sensitive ? Date().addingTimeInterval(TimeInterval(ClipSettings.sensitiveTTLMinutes * 60)) : nil))
    }

    private func captureImage(data: Data, sourceApp: String?) -> ClipRecord? {
        guard let image = NSImage(data: data),
              let tiff = image.tiffRepresentation,
              let rep = NSBitmapImageRep(data: tiff),
              let pngData = rep.representation(using: .png, properties: [:]),
              pngData.count <= 5 * 1024 * 1024 else { return nil }
        return ClipRecord(
            hash: sha256(pngData), kind: .image, content: nil,
            imageData: pngData, thumbData: thumbnail(of: image, maxDimension: 512),
            fileURLs: [], sourceApp: sourceApp, sensitive: false, expiresAt: nil)
    }

    private func thumbnail(of image: NSImage, maxDimension: CGFloat) -> Data? {
        let size = image.size
        guard size.width > 0, size.height > 0 else { return nil }
        let scale = min(1, maxDimension / max(size.width, size.height))
        let target = NSSize(width: max(1, size.width * scale), height: max(1, size.height * scale))
        guard let rep = NSBitmapImageRep(bitmapDataPlanes: nil,
                                         pixelsWide: Int(target.width), pixelsHigh: Int(target.height),
                                         bitsPerSample: 8, samplesPerPixel: 4, hasAlpha: true, isPlanar: false,
                                         colorSpaceName: .deviceRGB, bytesPerRow: 0, bitsPerPixel: 0) else { return nil }
        NSGraphicsContext.saveGraphicsState()
        NSGraphicsContext.current = NSGraphicsContext(bitmapImageRep: rep)
        image.draw(in: NSRect(origin: .zero, size: target))
        NSGraphicsContext.restoreGraphicsState()
        return rep.representation(using: .png, properties: [:])
    }

    private func classify(_ text: String) -> ClipKind {
        if text.hasPrefix("{") || text.hasPrefix("[") {
            if let data = text.data(using: .utf8),
               (try? JSONSerialization.jsonObject(with: data)) != nil {
                return .json
            }
        }
        if isURL(text) { return .url }
        if text.range(of: "^#([0-9a-fA-F]{3,4}|[0-9a-fA-F]{6}|[0-9a-fA-F]{8})$",
                      options: .regularExpression) != nil { return .color }
        if looksLikeCode(text) { return .code }
        return .text
    }

    private func isURL(_ text: String) -> Bool {
        guard !text.contains("\n"), text.count <= 2048 else { return false }
        guard let url = URL(string: text), let scheme = url.scheme?.lowercased() else { return false }
        return (scheme == "http" || scheme == "https") && url.host != nil
    }

    private func looksLikeCode(_ text: String) -> Bool {
        if text.contains("```") { return true }
        let markers = ["func ", "def ", "class ", "import ", "const ", "=>", "();", " {",
                       "</", "/>", "#!", "SELECT ", "public ", "private ", "return "]
        let score = markers.reduce(0) { $0 + (text.contains($1) ? 1 : 0) }
        return score >= 2
    }

    private func sha256(_ string: String) -> String { sha256(Data(string.utf8)) }

    private func sha256(_ data: Data) -> String {
        SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
    }
}

// MARK: - ViewModel
final class ClipboardViewModel: ObservableObject {
    @Published var clips: [Clip] = []
    @Published var query: String = ""
    @Published var selectedID: Int64?
    @Published var multiSelection: Set<Int64> = []
    @Published var detailClip: Clip?
    @Published var showSettings = false
    private var lastClickID: Int64?
    private var lastClickTime = Date.distantPast
    @Published var historyLimit: Int = ClipSettings.historyLimit {
        didSet { UserDefaults.standard.set(historyLimit, forKey: ClipSettings.historyLimitKey) }
    }
    @Published var recordImages: Bool = ClipSettings.recordImages {
        didSet { UserDefaults.standard.set(recordImages, forKey: ClipSettings.recordImagesKey) }
    }
    @Published var sensitiveTTL: Int = ClipSettings.sensitiveTTLMinutes {
        didSet { UserDefaults.standard.set(sensitiveTTL, forKey: ClipSettings.sensitiveTTLKey) }
    }
    @Published var floatOnWriteBack: Bool = ClipSettings.floatOnWriteBack {
        didSet { UserDefaults.standard.set(floatOnWriteBack, forKey: ClipSettings.floatOnWriteBackKey) }
    }

    private let store = ClipboardStore.shared
    private var pinyinIndex: [Int64: (full: String, initials: String)] = [:]
    private var indexReady = false
    private var observer: NSObjectProtocol?
    private var expiryTimer: Timer?
    private var indexGeneration = UUID()

    init() {
        load()
        let timer = Timer(timeInterval: 15, repeats: true) { [weak self] _ in
            guard let self, self.clips.contains(where: \.isExpired) else { return }
            self.store.purge()
        }
        RunLoop.main.add(timer, forMode: .common)
        expiryTimer = timer
        observer = NotificationCenter.default.addObserver(
            forName: .clipStoreDidChange, object: nil, queue: .main
        ) { [weak self] _ in self?.load() }
    }

    deinit {
        expiryTimer?.invalidate()
        if let o = observer { NotificationCenter.default.removeObserver(o) }
    }

    func load() {
        clips = store.loadAll()
        let live = Set(clips.map(\.id))
        if let id = selectedID, !live.contains(id) { selectedID = nil }
        multiSelection.formIntersection(live)
        if let detail = detailClip, !live.contains(detail.id) { detailClip = nil }
        pinyinIndex = pinyinIndex.filter { live.contains($0.key) }
        let generation = UUID(); indexGeneration = generation
        let cached = pinyinIndex
        let snapshot = clips.map { ($0.id, $0.content ?? $0.preview) }
        DispatchQueue.global(qos: .utility).async { [weak self] in
            var index = cached
            for (id, text) in snapshot where index[id] == nil && !text.isEmpty { index[id] = Pinyin.of(text) }
            DispatchQueue.main.async {
                guard let self, self.indexGeneration == generation else { return }
                self.pinyinIndex = index
                self.indexReady = true
                self.objectWillChange.send()
            }
        }
    }

    // MARK: 过滤(子串 + 拼音全拼 + 首字母子序列)

    var visibleClips: [Clip] {
        let q = query.trimmingCharacters(in: .whitespacesAndNewlines).lowercased()
        let active = clips.filter { !$0.isExpired }
        guard !q.isEmpty else { return active }
        let asciiOnly = q.allSatisfy { $0.isASCII }
        return active.filter { clip in
            if let content = clip.content, content.lowercased().contains(q) { return true }
            if clip.kind == .file,
               clip.fileURLs.contains(where: { $0.lastPathComponent.lowercased().contains(q) }) { return true }
            guard indexReady, let py = pinyinIndex[clip.id] else { return false }
            if py.full.contains(q) { return true }
            if asciiOnly, q.count <= 12, isSubsequence(needle: q, haystack: py.initials) { return true }
            return false
        }
    }

    var pinnedClips: [Clip] { visibleClips.filter(\.pinned) }
    var recentClips: [Clip] { visibleClips.filter { !$0.pinned } }

    /// 单次遍历分区, 避免父视图 body 里多次触发 visibleClips 全量过滤
    var visiblePartition: (pinned: [Clip], recent: [Clip]) {
        var pinned: [Clip] = []
        var recent: [Clip] = []
        for clip in visibleClips {
            if clip.pinned { pinned.append(clip) } else { recent.append(clip) }
        }
        return (pinned, recent)
    }

    var selectedClip: Clip? {
        guard let sel = selectedID else { return nil }
        return visibleClips.first { $0.id == sel }
    }

    private func isSubsequence(needle: String, haystack: String) -> Bool {
        var it = haystack.makeIterator()
        for ch in needle {
            var matched = false
            while let h = it.next() {
                if h == ch { matched = true; break }
            }
            if !matched { return false }
        }
        return true
    }

    // MARK: 交互

    func moveSelection(_ delta: Int) {
        let list = visibleClips
        guard !list.isEmpty else { return }
        guard let current = selectedID, let idx = list.firstIndex(where: { $0.id == current }) else {
            selectedID = list.first?.id
            return
        }
        selectedID = list[max(0, min(list.count - 1, idx + delta))].id
    }

    func handleRowClick(_ clip: Clip) {
        let now = Date()
        // 双击判定自实现: 双击窗口内同一行的第二次点击 → 直接写回。
        // 不能用 SwiftUI count:2 手势 —— 它会让每次单击等歧义窗口, 选中高亮延迟就是这么来的。
        // 窗口跟随系统双击速度设置(NSEvent.doubleClickInterval), 比写死 0.3s 更容易命中。
        if lastClickID == clip.id, now.timeIntervalSince(lastClickTime) < NSEvent.doubleClickInterval {
            lastClickID = nil
            lastClickTime = .distantPast
            writeBack([clip])
            return
        }
        lastClickID = clip.id
        lastClickTime = now
        if NSEvent.modifierFlags.contains(.command) {
            if multiSelection.contains(clip.id) {
                multiSelection.remove(clip.id)
            } else {
                if multiSelection.isEmpty, let sel = selectedID { multiSelection.insert(sel) }
                multiSelection.insert(clip.id)
            }
        } else {
            multiSelection = []
            selectedID = clip.id
        }
    }

    func togglePin(_ clip: Clip) { store.setPinned(id: clip.id, pinned: !clip.pinned) }

    func delete(_ clip: Clip) {
        store.delete(id: clip.id)
        if selectedID == clip.id { selectedID = visibleClips.first?.id }
        multiSelection.remove(clip.id)
    }

    func writeBackSelection() {
        let targets: [Clip]
        if multiSelection.count > 1 {
            targets = visibleClips.filter { multiSelection.contains($0.id) }
        } else if let clip = selectedClip {
            targets = [clip]
        } else {
            targets = Array(visibleClips.prefix(1))
        }
        guard !targets.isEmpty else { return }
        writeBack(targets)
    }

    /// 写回系统剪切板(不做自动粘贴, 零权限)。写后由窗口壳关闭面板并归还焦点。
    func writeBack(_ targets: [Clip]) {
        guard !targets.isEmpty, targets.allSatisfy({ !$0.isExpired }) else { load(); return }
        let pb = NSPasteboard.general
        pb.clearContents()
        if targets.count == 1, let clip = targets.first {
            switch clip.kind {
            case .image:
                if let data = clip.imageData {
                    pb.setData(data, forType: .png)
                    if let img = NSImage(data: data), let tiff = img.tiffRepresentation {
                        pb.setData(tiff, forType: .tiff)
                    }
                }
            case .file:
                pb.writeObjects(clip.fileURLs as [NSURL])
            default:
                pb.setString(clip.content ?? "", forType: .string)
            }
        } else {
            let texts = targets.compactMap { clip -> String? in
                switch clip.kind {
                case .image, .file: return nil
                default: return clip.content
                }
            }
            if !texts.isEmpty { pb.setString(texts.joined(separator: "\n"), forType: .string) }
            let urls = targets.filter { $0.kind == .file }.flatMap { $0.fileURLs }
            if !urls.isEmpty { pb.writeObjects(urls as [NSURL]) }
        }
        ClipboardMonitor.shared.noteSelfWrite()
        // 写回浮顶: 刚用过的条目排到最上面(可在设置关闭)
        if ClipSettings.floatOnWriteBack {
            for clip in targets { store.touch(id: clip.id) }
        }
        NotificationCenter.default.post(name: .clipWriteBackDone, object: nil)
    }

    /// URL 去追踪参数后写回(utm_*/fbclid/gclid/spm…)
    func copyCleanURL(_ clip: Clip) {
        guard !clip.isExpired, clip.kind == .url, let raw = clip.content,
              var components = URLComponents(string: raw) else { return }
        let tracking: Set<String> = ["utm_source", "utm_medium", "utm_campaign", "utm_term", "utm_content",
                                     "fbclid", "gclid", "spm", "scm", "share_token", "share_id", "isappinstalled"]
        components.queryItems = components.queryItems?.filter { !tracking.contains($0.name.lowercased()) }
        if components.queryItems?.isEmpty == true { components.queryItems = nil }
        guard let cleaned = components.string else { return }
        let pb = NSPasteboard.general
        pb.clearContents()
        pb.setString(cleaned, forType: .string)
        ClipboardMonitor.shared.noteSelfWrite()
    }

    func applyCleanup() { store.purge() }
}

// MARK: - 视图
struct ClipboardBoardView: View {
    @EnvironmentObject var vm: ClipboardViewModel
    @EnvironmentObject var theme: ThemeManager
    @Environment(\.openSettings) private var openSettings
    @EnvironmentObject var fm: FontManager
    var popoverMode: Bool = false
    @FocusState private var searchFocused: Bool

    var body: some View {
        VStack(spacing: 0) {
            VStack(spacing: 0) {
                header
                searchBar
            }
            .background(theme.current.cardFill.opacity(theme.current.cardFillOpacity * 0.78))
            Divider().opacity(0.4)
            clipList
            Divider().opacity(0.4)
            footer
        }
        .background(ThemeBackground().environmentObject(theme))
        .overlay {
            if let detail = vm.detailClip {
                ClipDetailOverlay(clip: detail) { vm.detailClip = nil }
            } else if vm.showSettings {
                ClipSettingsOverlay { vm.showSettings = false }
            }
        }
        .onAppear {
            searchFocused = true
            if vm.selectedID == nil { vm.selectedID = vm.visibleClips.first?.id }
        }
        .onKeyPress(.escape) {
            if vm.detailClip != nil { vm.detailClip = nil; return .handled }
            if vm.showSettings { vm.showSettings = false; return .handled }
            NotificationCenter.default.post(name: .clipDismiss, object: nil)
            return .handled
        }
    }

    // MARK: Header

    private var header: some View {
        HStack(spacing: 8) {
            Text("剪切板")
                .font(fm.font(13).weight(.semibold))
                .foregroundStyle(theme.current.textPrimary)
            Text("\(vm.clips.count)")
                .font(.system(size: 10, weight: .medium, design: .monospaced))
                .foregroundStyle(theme.current.textSecondary)
                .padding(.horizontal, 6)
                .padding(.vertical, 1.5)
                .background(Capsule().fill(theme.current.cardFill.opacity(theme.current.cardFillOpacity)))
            Spacer()
            if !popoverMode {
                Button {
                    NotificationCenter.default.post(name: .clipDismiss, object: nil)
                } label: {
                    Image(systemName: "xmark").dboardFont(size: 9, weight: .semibold)
                }
                .buttonStyle(.plain)
                .foregroundStyle(theme.current.textSecondary)
            } else {
                TearOffButton(key: "ClipboardBoard")
            }
            Button {
                WorkspacePreferences.shared.settingsPage = .clipboard
                openSettings()
            } label: {
                Image(systemName: "gearshape").dboardFont(size: 11)
            }
            .buttonStyle(.plain)
            .foregroundStyle(theme.current.textSecondary)
        }
        .padding(.horizontal, 12)
        .padding(.top, 10)
        .padding(.bottom, 6)
        .tearOffHandle("ClipboardBoard", enabled: popoverMode)
    }

    // MARK: 搜索栏

    private var searchBar: some View {
        HStack(spacing: 6) {
            Image(systemName: "magnifyingglass")
                .dboardFont(size: 11)
                .foregroundStyle(theme.current.textTertiary)
            TextField("搜索：子串 / 拼音 / 首字母", text: $vm.query)
                .textFieldStyle(.plain)
                .font(fm.font(12))
                .foregroundStyle(theme.current.textPrimary)
                .focused($searchFocused)
                .onSubmit { vm.writeBackSelection() }
                .onKeyPress(keys: [.upArrow, .downArrow, .return, .delete]) { press in
                    switch press.key {
                    case .upArrow:
                        vm.moveSelection(-1)
                        return .handled
                    case .downArrow:
                        vm.moveSelection(1)
                        return .handled
                    case .return:
                        if press.modifiers.contains(.command) {
                            if let sel = vm.selectedClip { vm.togglePin(sel) }
                            return .handled
                        }
                        vm.writeBackSelection()
                        return .handled
                    case .delete:
                        if vm.query.isEmpty, let sel = vm.selectedClip {
                            vm.delete(sel)
                            return .handled
                        }
                        return .ignored
                    default:
                        return .ignored
                    }
                }
            if !vm.query.isEmpty {
                Button {
                    vm.query = ""
                } label: {
                    Image(systemName: "xmark.circle.fill")
                        .dboardFont(size: 11)
                        .foregroundStyle(theme.current.textMuted)
                }
                .buttonStyle(.plain)
            }
        }
        .padding(.horizontal, 8)
        .padding(.vertical, 7)
        .background(RoundedRectangle(cornerRadius: 10).fill(theme.current.cardFill.opacity(theme.current.cardFillOpacity * 0.6)))
        .padding(.horizontal, 10)
        .padding(.bottom, 8)
    }

    // MARK: 列表

    @ViewBuilder
    private var clipList: some View {
        let parts = vm.visiblePartition
        ScrollViewReader { proxy in
            ScrollView {
                LazyVStack(spacing: 4) {
                    if !parts.pinned.isEmpty {
                        sectionHeader("置顶", count: parts.pinned.count)
                        ForEach(parts.pinned) { clip in row(for: clip) }
                    }
                    if !parts.recent.isEmpty {
                        sectionHeader("历史", count: parts.recent.count)
                        ForEach(parts.recent) { clip in row(for: clip) }
                    }
                    if parts.pinned.isEmpty && parts.recent.isEmpty { emptyState }
                }
                .padding(.horizontal, 8)
                .padding(.vertical, 6)
            }
            .onChange(of: vm.selectedID) { _, newValue in
                // 键盘连续移动不带动画, 避免动画堆叠造成卡顿感
                if let id = newValue { proxy.scrollTo(id, anchor: nil) }
            }
        }
    }

    private func row(for clip: Clip) -> some View {
        ClipRow(
            clip: clip,
            isSelected: vm.multiSelection.contains(clip.id) || vm.selectedID == clip.id,
            theme: theme.current,
            font: fm.current,
            // 点击后焦点还给搜索框, 保证鼠标选完仍能 ↑↓/Enter 键盘操作
            onTap: { vm.handleRowClick(clip); searchFocused = true },
            onTogglePin: { vm.togglePin(clip) },
            onCleanURL: { vm.copyCleanURL(clip) },
            onDetail: { vm.detailClip = clip },
            onDelete: { vm.delete(clip) }
        )
        .equatable()
        .id(clip.id)
    }

    private func sectionHeader(_ title: String, count: Int) -> some View {
        HStack(spacing: 6) {
            Text(title)
                .dboardFont(size: 10, weight: .semibold)
                .foregroundStyle(theme.current.textMuted)
            Rectangle()
                .fill(theme.current.separator.opacity(0.7))
                .frame(height: 0.5)
            Text("\(count)")
                .font(.system(size: 9, design: .monospaced))
                .foregroundStyle(theme.current.textMuted)
        }
        .padding(.horizontal, 10)
        .padding(.top, 8)
        .padding(.bottom, 2)
    }

    private var emptyState: some View {
        VStack(spacing: 10) {
            ZStack {
                Circle()
                    .fill(theme.current.cardFill.opacity(theme.current.cardFillOpacity * 0.7))
                    .frame(width: 54, height: 54)
                Image(systemName: vm.query.isEmpty ? "clipboard" : "magnifyingglass")
                    .dboardFont(size: 22, weight: .light)
                    .foregroundStyle(theme.current.textMuted)
            }
            Text(vm.query.isEmpty ? "暂无历史" : "没有匹配的内容")
                .font(fm.font(12.5))
                .foregroundStyle(theme.current.textSecondary)
            Text(vm.query.isEmpty ? "复制任意内容（⌘C），会自动出现在这里" : "换个关键词试试，支持拼音和首字母")
                .dboardFont(size: 10)
                .foregroundStyle(theme.current.textMuted)
        }
        .frame(maxWidth: .infinity)
        .padding(.vertical, 48)
    }

    // MARK: Footer

    private var footer: some View {
        HStack(spacing: 8) {
            if vm.multiSelection.count > 1 {
                Button {
                    vm.writeBackSelection()
                } label: {
                    Text("合并复制 \(vm.multiSelection.count) 条")
                        .dboardFont(size: 11, weight: .medium)
                }
                .buttonStyle(.plain)
                .foregroundStyle(.white)
                .padding(.horizontal, 8).padding(.vertical, 3)
                .background(Capsule().fill(theme.current.accentPrimary))
            } else {
                Text(vm.query.isEmpty
                     ? "双击 / Enter 写回 · ⌘点击多选"
                     : "\(vm.visibleClips.count) 条匹配")
                    .dboardFont(size: 10)
                    .foregroundStyle(theme.current.textMuted)
            }
            Spacer()
            Text("⌥V").font(.system(size: 9, weight: .medium, design: .monospaced))
                .foregroundStyle(theme.current.textTertiary)
        }
        .padding(.horizontal, 12)
        .padding(.vertical, 7)
        .background(theme.current.cardFill.opacity(theme.current.cardFillOpacity * 0.78))
    }
}

// MARK: - 行组件
// MARK: - 行渲染缓存(避免每次选择变化重复解码 PNG / 查询文件图标)
enum ClipAssetCache {
    static let thumbs: NSCache<NSNumber, NSImage> = {
        let cache = NSCache<NSNumber, NSImage>()
        cache.countLimit = 200
        return cache
    }()
    static let fileIcons: NSCache<NSString, NSImage> = {
        let cache = NSCache<NSString, NSImage>()
        cache.countLimit = 200
        return cache
    }()

    static func thumb(for clip: Clip) -> NSImage? {
        let key = NSNumber(value: clip.id)
        if let hit = thumbs.object(forKey: key) { return hit }
        guard let data = clip.thumbData, let img = NSImage(data: data) else { return nil }
        thumbs.setObject(img, forKey: key)
        return img
    }

    static func fileIcon(for path: String) -> NSImage {
        let key = path as NSString
        if let hit = fileIcons.object(forKey: key) { return hit }
        let img = NSWorkspace.shared.icon(forFile: path)
        fileIcons.setObject(img, forKey: key)
        return img
    }
}

// MARK: - 行组件
// 纯值输入 + Equatable: 选择移动时只有状态真正变化的行会重绘,
// 其余行命中 == 跳过 body; 行内不观察 vm, 避免全列表重绘。
struct ClipRow: View, Equatable {
    let clip: Clip
    let isSelected: Bool
    let theme: DBoardTheme
    let font: DBoardFont
    let onTap: () -> Void
    let onTogglePin: () -> Void
    let onCleanURL: () -> Void
    let onDetail: () -> Void
    let onDelete: () -> Void

    @State private var isHovered = false

    static func == (lhs: ClipRow, rhs: ClipRow) -> Bool {
        lhs.clip.id == rhs.clip.id
            && lhs.clip.pinned == rhs.clip.pinned
            && lhs.clip.sensitive == rhs.clip.sensitive
            && lhs.clip.createdAt == rhs.clip.createdAt
            && lhs.isSelected == rhs.isSelected
            && lhs.theme.id == rhs.theme.id
            && lhs.font.id == rhs.font.id
    }

    var body: some View {
        Button(action: onTap) {
            rowContent
        }
        .buttonStyle(ClipRowPressStyle())
        .contextMenu {
            Button(clip.pinned ? "取消置顶" : "置顶") { onTogglePin() }
            if clip.kind == .url {
                Button("复制干净链接（去追踪参数）") { onCleanURL() }
            }
            Button("详情") { onDetail() }
            Divider()
            Button("删除", role: .destructive) { onDelete() }
        }
    }

    private var rowContent: some View {
        HStack(spacing: 8) {
            iconView
                // 图片行选中↔未选中的大小切换做 150ms 过渡
                .animation(.easeOut(duration: 0.15), value: isSelected)
            VStack(alignment: .leading, spacing: 2) {
                Text(clip.preview.isEmpty ? "(空)" : clip.preview)
                    .font(clip.isMonospaced
                          ? .system(size: 11.5, design: .monospaced)
                          : Font.custom(font.fontName, size: 12 * font.sizeScale))
                    .foregroundStyle(theme.textPrimary)
                    .lineLimit(2)
                    .multilineTextAlignment(.leading)
                metaLine
            }
            Spacer(minLength: 0)
            if clip.sensitive {
                Image(systemName: "lock.fill")
                    .dboardFont(size: 9)
                    .foregroundStyle(.orange.opacity(0.85))
            }
            if clip.pinned {
                Image(systemName: "pin.fill")
                    .dboardFont(size: 9)
                    .foregroundStyle(theme.accentPrimary)
            }
        }
        .padding(8)
        .background(RoundedRectangle(cornerRadius: 8)
            .fill(isSelected
                  ? theme.accentPrimary.opacity(0.16)
                  : theme.cardFill.opacity(theme.cardFillOpacity * (isHovered ? 0.85 : 0.42))))
        .overlay(RoundedRectangle(cornerRadius: 8)
            .stroke(isSelected ? theme.accentPrimary.opacity(0.5) : .clear, lineWidth: 1))
        .contentShape(Rectangle())
        .onHover { hovering in isHovered = hovering }
        // 选中/悬停用 100ms 内的快出过渡: 有动效但不拖沓
        .animation(.easeOut(duration: 0.1), value: isSelected)
        .animation(.easeOut(duration: 0.12), value: isHovered)
    }

    private var metaLine: some View {
        HStack(spacing: 6) {
            Text(relativeTime(clip.createdAt))
            if let name = appName(for: clip.sourceApp) {
                Text("·")
                Text(name)
            }
            Text("·")
            Text(clip.kind.label)
        }
        .dboardFont(size: 10)
        .foregroundStyle(theme.textTertiary)
        .lineLimit(1)
    }

    @ViewBuilder
    private var iconView: some View {
        switch clip.kind {
        case .image:
            // 选中才展开大图预览, 未选中保持 32px 小图让列表紧凑
            if isSelected {
                imagePreviewLarge
            } else {
                imagePreviewSmall
            }
        case .file:
            if let first = clip.fileURLs.first {
                let icon = ClipAssetCache.fileIcon(for: first.path)
                Image(nsImage: icon)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(width: 28, height: 28)
            } else {
                typeIcon
            }
        case .color:
            ZStack {
                RoundedRectangle(cornerRadius: 6)
                    .fill(Color(hex: clip.content ?? "#888888"))
                    .frame(width: 26, height: 26)
                RoundedRectangle(cornerRadius: 6)
                    .stroke(theme.separator, lineWidth: 1)
                    .frame(width: 26, height: 26)
            }
        default:
            typeIcon
        }
    }

    private var typeIcon: some View {
        Image(systemName: clip.kind.icon)
            .dboardFont(size: 14, weight: .regular)
            .foregroundStyle(theme.textTertiary)
            .frame(width: 32, height: 32)
            .background(RoundedRectangle(cornerRadius: 7).fill(theme.cardFill.opacity(theme.cardFillOpacity * 0.55)))
    }

    /// 未选中: 32px 方形小图, 与文本行图标对齐, 列表紧凑
    private var imagePreviewSmall: some View {
        Group {
            if let img = ClipAssetCache.thumb(for: clip) {
                Image(nsImage: img)
                    .resizable()
                    .aspectRatio(contentMode: .fill)
                    .frame(width: 32, height: 32)
                    .clipShape(RoundedRectangle(cornerRadius: 6))
            } else {
                typeIcon
            }
        }
    }

    /// 选中: 行内展开大图预览(最高 88pt), 不用进详情才能看
    private var imagePreviewLarge: some View {
        Group {
            if let img = ClipAssetCache.thumb(for: clip) {
                Image(nsImage: img)
                    .resizable()
                    .aspectRatio(contentMode: .fit)
                    .frame(maxWidth: 140, maxHeight: 88)
                    .clipShape(RoundedRectangle(cornerRadius: 6))
                    .overlay(RoundedRectangle(cornerRadius: 6).stroke(theme.separator.opacity(0.6), lineWidth: 1))
            } else {
                typeIcon
            }
        }
    }
}

/// 按压反馈: 鼠标按下瞬间轻微变暗(不等抬起), 松开恢复 —— 点击响应的"手感"来源
struct ClipRowPressStyle: ButtonStyle {
    func makeBody(configuration: Configuration) -> some View {
        configuration.label
            .brightness(configuration.isPressed ? -0.06 : 0)
            .animation(.easeOut(duration: 0.08), value: configuration.isPressed)
    }
}

private var appNameCache: [String: String] = [:]

func appName(for bundleID: String?) -> String? {
    guard let bundleID, !bundleID.isEmpty else { return nil }
    if let cached = appNameCache[bundleID] { return cached }
    let name = NSRunningApplication.runningApplications(withBundleIdentifier: bundleID).first?.localizedName
        ?? bundleID.components(separatedBy: ".").last
        ?? bundleID
    appNameCache[bundleID] = name
    return name
}

func relativeTime(_ date: Date) -> String {
    let interval = Date().timeIntervalSince(date)
    if interval < 60 { return "刚刚" }
    if interval < 3600 { return "\(Int(interval / 60))分钟前" }
    if interval < 86400 { return "\(Int(interval / 3600))小时前" }
    if interval < 86400 * 7 { return "\(Int(interval / 86400))天前" }
    let formatter = DateFormatter()
    formatter.dateFormat = "MM-dd HH:mm"
    return formatter.string(from: date)
}

// MARK: - 详情浮层
struct ClipDetailOverlay: View {
    @EnvironmentObject var vm: ClipboardViewModel
    @EnvironmentObject var theme: ThemeManager
    @EnvironmentObject var fm: FontManager
    let clip: Clip
    let onClose: () -> Void

    var body: some View {
        VStack(spacing: 0) {
            HStack {
                Text("详情")
                    .font(fm.font(13).weight(.semibold))
                    .foregroundStyle(theme.current.textPrimary)
                Text(clip.kind.label)
                    .dboardFont(size: 9, weight: .medium)
                    .foregroundStyle(theme.current.textSecondary)
                    .padding(.horizontal, 6)
                    .padding(.vertical, 2)
                    .background(Capsule().fill(theme.current.cardFill.opacity(theme.current.cardFillOpacity)))
                Spacer()
                Button {
                    vm.writeBack([clip])
                } label: {
                    Text("写回剪切板").dboardFont(size: 11, weight: .medium)
                }
                .buttonStyle(.plain)
                .foregroundStyle(.white)
                .padding(.horizontal, 10).padding(.vertical, 4)
                .background(Capsule().fill(theme.current.accentPrimary))
                Button {
                    onClose()
                } label: {
                    Image(systemName: "xmark").dboardFont(size: 10, weight: .semibold)
                }
                .buttonStyle(.plain)
                .foregroundStyle(theme.current.textSecondary)
            }
            .padding(12)

            Divider().opacity(0.4)

            ScrollView {
                VStack(alignment: .leading, spacing: 10) {
                    if clip.kind == .image, let data = clip.imageData, let img = NSImage(data: data) {
                        Image(nsImage: img)
                            .resizable()
                            .aspectRatio(contentMode: .fit)
                            .frame(maxWidth: .infinity)
                            .clipShape(RoundedRectangle(cornerRadius: 8))
                    } else if clip.kind == .file {
                        ForEach(clip.fileURLs, id: \.absoluteString) { url in
                            HStack(spacing: 6) {
                                Image(systemName: "doc").dboardFont(size: 11)
                                Text(url.path)
                                    .font(.system(size: 11, design: .monospaced))
                                    .textSelection(.enabled)
                            }
                            .foregroundStyle(theme.current.textSecondary)
                        }
                    } else {
                        Text(displayText)
                            .dboardFont(size: 11.5, design: clip.isMonospaced ? .monospaced : .default)
                            .foregroundStyle(theme.current.textPrimary)
                            .textSelection(.enabled)
                            .frame(maxWidth: .infinity, alignment: .leading)
                            .padding(10)
                            .background(RoundedRectangle(cornerRadius: 10)
                                .fill(theme.current.cardFill.opacity(theme.current.cardFillOpacity * 0.55)))
                    }
                    metaFooter
                }
                .padding(12)
            }
        }
        // 毛玻璃皮肤下 background 是 clear, 必须走 ThemeBackground 才有底
        .background(ThemeBackground().environmentObject(theme))
    }

    private var displayText: String {
        let raw = clip.content ?? ""
        if clip.kind == .json, let pretty = prettyJSON(raw) { return pretty }
        return raw
    }

    private var metaFooter: some View {
        HStack(spacing: 8) {
            if let content = clip.content { Text("\(content.count) 字符") }
            if let name = appName(for: clip.sourceApp) { Text("来自 \(name)") }
            Text(relativeTime(clip.createdAt))
            if clip.sensitive {
                Text("敏感内容 · 到期自动删除")
                    .foregroundStyle(.orange)
            }
        }
        .dboardFont(size: 10)
        .foregroundStyle(theme.current.textTertiary)
    }

    private func prettyJSON(_ text: String) -> String? {
        guard let data = text.data(using: .utf8),
              let obj = try? JSONSerialization.jsonObject(with: data) else { return nil }
        guard let pretty = try? JSONSerialization.data(
            withJSONObject: obj,
            options: [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]) else { return nil }
        return String(data: pretty, encoding: .utf8)
    }
}

