// MARK: - 窗口控制器
/// ⌥V 热键面板: nonactivating → 不抢前台 app 焦点; canBecomeKey → 搜索框/键盘操作照常
private final class ClipHotKeyPanel: NSPanel {
    override var canBecomeKey: Bool { true }
    override var canBecomeMain: Bool { false }
}

final class ClipboardBoardWindowController {
    static let shared = ClipboardBoardWindowController()

    private var window: NSWindow?
    private var popover: NSPopover?
    private var clickMonitor: Any?
    private var keyMonitor: Any?
    private var popCloseObserver: Any?
    private var writeBackObserver: Any?
    private var dismissObserver: Any?
    private var windowCloseObserver: Any?
    private var panelClickMonitor: Any?
    private var panelLocalClickMonitor: Any?
    private var winWriteBackObserver: Any?
    private let tearOff = TearOffObserver()
    private let vm = ClipboardViewModel()
    /// 弹出前的前台 app: 关闭时归还焦点, 保证用户 ⌘V 粘回原处
    private var lastFrontmost: NSRunningApplication?

    func togglePopover(relativeTo button: NSStatusBarButton) {
        if let pop = popover, pop.isShown {
            closePopover()
            return
        }
        lastFrontmost = NSWorkspace.shared.frontmostApplication
        let screenH = (button.window?.screen ?? NSScreen.main)?.visibleFrame.height ?? 900
        let popH = min(max(screenH * 0.66, 400), 720)
        let popW: CGFloat = 440

        let pop = NSPopover()
        pop.behavior = .transient
        // 关闭下滑动画: ⌥V 呼出要像 Raycast 一样瞬开, 200ms 动画只会显得迟钝
        pop.animates = false
        let host = NSHostingController(rootView:
            ClipboardBoardView(popoverMode: true)
                .environmentObject(vm)
                .environmentObject(ThemeManager.shared)
                .dboardFont(size: 13).environmentObject(FontManager.shared)
                .frame(width: popW, height: popH))
        pop.contentSize = NSSize(width: popW, height: popH)
        pop.contentViewController = host
        pop.show(relativeTo: button.bounds, of: button, preferredEdge: .minY)
        popover = pop
        vm.query = ""
        vm.selectedID = vm.visibleClips.first?.id
        NSApp.activate(ignoringOtherApps: true)

        clickMonitor = NSEvent.addGlobalMonitorForEvents(
            matching: [.leftMouseDown, .rightMouseDown]) { [weak self] _ in
            guard let self, let p = self.popover, p.isShown else { return }
            DispatchQueue.main.async { self.closePopover() }
        }
        keyMonitor = NSEvent.addLocalMonitorForEvents(matching: .keyDown) { [weak self] event in
            // Esc: 详情/设置浮层由视图内部消化, 这里只负责关 popover
            if event.keyCode == 53, let p = self?.popover, p.isShown {
                if self?.vm.detailClip == nil, self?.vm.showSettings == false {
                    self?.closePopover()
                    return nil
                }
            }
            return event
        }
        writeBackObserver = NotificationCenter.default.addObserver(
            forName: .clipWriteBackDone, object: nil, queue: .main) { [weak self] _ in
            self?.closePopover()
        }
        popCloseObserver = NotificationCenter.default.addObserver(
            forName: NSPopover.didCloseNotification, object: pop, queue: .main) { [weak self] _ in
            self?.teardownMonitors()
        }
        tearOff.install(key: "ClipboardBoard") { [weak self] in
            guard let self else { return }
            self.closePopover()
            self.show()
        }
    }

    func show() {
        let front = NSWorkspace.shared.frontmostApplication
        if front?.bundleIdentifier != Bundle.main.bundleIdentifier { lastFrontmost = front }
        if let w = window {
            // 每次呼出都是全新状态: 清搜索、选中第一条(不复用上次的选中/搜索残留)
            vm.query = ""
            vm.selectedID = vm.visibleClips.first?.id
            Self.centerOnMouseScreen(w)
            w.makeKeyAndOrderFront(nil)
            return
        }
        if lastFrontmost == nil {
            lastFrontmost = NSWorkspace.shared.frontmostApplication
        }
        vm.query = ""
        vm.selectedID = vm.visibleClips.first?.id
        let view = ClipboardBoardView(popoverMode: false)
            .environmentObject(vm)
            .environmentObject(ThemeManager.shared)
            .dboardFont(size: 13).environmentObject(FontManager.shared)
        let host = NSHostingController(rootView: view)
        // macOS Tahoe: 后台 LSUIElement app 抢不到前台焦点(activate 被系统拒绝) →
        // 改用 .nonactivatingPanel 浮动面板: 不激活 D板、不抢前台 app, 直接浮到最上层收键盘
        let win = ClipHotKeyPanel(contentViewController: host)
        win.title = "剪切板历史"
        win.titleVisibility = .hidden
        win.titlebarAppearsTransparent = true
        win.setContentSize(NSSize(width: 460, height: 640))
        win.styleMask = [.titled, .closable, .fullSizeContentView, .nonactivatingPanel]
        // 临时弹窗: 隐藏左上角交通灯(关闭/缩小/放大), 关闭只走 Esc / 点外面 / 写回
        for btn in [NSWindow.ButtonType.closeButton, .miniaturizeButton, .zoomButton] {
            win.standardWindowButton(btn)?.isHidden = true
        }
        win.isReleasedWhenClosed = false
        // 窗口透明度: 只在 nativeBlur 主题下透出桌面壁纸, 其它主题保持不透明避免顶栏透视
        let _needsTransparent = ThemeManager.shared.current.nativeBlur
        win.isOpaque = !_needsTransparent
        win.backgroundColor = _needsTransparent ? .clear : .windowBackgroundColor
        win.level = .floating
        win.isFloatingPanel = true
        win.hidesOnDeactivate = false   // app 始终"未激活", 此值为 true 面板会一直隐身
        win.collectionBehavior = [.moveToActiveSpace, .fullScreenPrimary]
        win.contentMinSize = NSSize(width: 380, height: 420)
        Self.centerOnMouseScreen(win)
        win.makeKeyAndOrderFront(nil)
        window = win

        // 写回完成(双击 / Enter) → 使命结束, 自动收起
        winWriteBackObserver = NotificationCenter.default.addObserver(
            forName: .clipWriteBackDone, object: nil, queue: .main) { [weak self] _ in
            self?.closeWindow()
        }

        // 点击面板以外任意位置 → 自动收起(不拦截那次点击本身, 只关自己)
        panelClickMonitor = NSEvent.addGlobalMonitorForEvents(
            matching: [.leftMouseDown, .rightMouseDown]) { [weak self] _ in
            guard let self, let w = self.window else { return }
            if !w.frame.contains(NSEvent.mouseLocation) { self.closeWindow() }
        }
        panelLocalClickMonitor = NSEvent.addLocalMonitorForEvents(
            matching: [.leftMouseDown, .rightMouseDown]) { [weak self] event in
            guard let self, let w = self.window else { return event }
            if event.window !== w { self.lastFrontmost = nil; self.closeWindow() }
            return event
        }

        dismissObserver = NotificationCenter.default.addObserver(
            forName: .clipDismiss, object: nil, queue: .main) { [weak self] _ in
            self?.closeWindow()
        }
        windowCloseObserver = NotificationCenter.default.addObserver(
            forName: NSWindow.willCloseNotification, object: win, queue: .main) { [weak self] _ in
            self?.window = nil
            if let o = self?.dismissObserver { NotificationCenter.default.removeObserver(o); self?.dismissObserver = nil }
            if let o = self?.windowCloseObserver { NotificationCenter.default.removeObserver(o); self?.windowCloseObserver = nil }
            if let m = self?.panelClickMonitor { NSEvent.removeMonitor(m); self?.panelClickMonitor = nil }
            if let m = self?.panelLocalClickMonitor { NSEvent.removeMonitor(m); self?.panelLocalClickMonitor = nil }
            if let o = self?.winWriteBackObserver { NotificationCenter.default.removeObserver(o); self?.winWriteBackObserver = nil }
            self?.restoreFocus()
        }
    }

    /// 调试: 自报窗口状态(终端无 TCC 权限, 只能 app 内自查)
    func debugWindowInfo() -> String {
        let front = NSWorkspace.shared.frontmostApplication?.localizedName ?? "?"
        if let w = window {
            return "window exists visible=\(w.isVisible) key=\(w.isKeyWindow) frame=\(w.frame) appActive=\(NSApp.isActive) front=\(front)"
        }
        return "window NIL appActive=\(NSApp.isActive) front=\(front)"
    }

    /// 弹在鼠标所在屏幕(多显示器)的 visibleFrame 中央, 而不是可能不亮的 main 屏
    private static func centerOnMouseScreen(_ win: NSWindow) {
        let mouse = NSEvent.mouseLocation
        let scr = NSScreen.screens.first { $0.frame.contains(mouse) } ?? NSScreen.main ?? NSScreen.screens.first
        guard let f = scr?.visibleFrame else { return }
        var fr = win.frame
        fr.origin.x = f.minX + (f.width - fr.width) / 2
        fr.origin.y = f.minY + (f.height - fr.height) / 2
        win.setFrame(fr, display: false)
    }

    private func closePopover() {
        popover?.performClose(nil)
        popover = nil
        teardownMonitors()
        restoreFocus()
    }

    private func closeWindow() {
        window?.performClose(nil)
    }

    private func restoreFocus() {
        if NSApp.isActive, let app = lastFrontmost, !app.isTerminated,
           app.bundleIdentifier != Bundle.main.bundleIdentifier {
            app.activate()
        }
        lastFrontmost = nil
    }

    private func teardownMonitors() {
        if let m = clickMonitor { NSEvent.removeMonitor(m); clickMonitor = nil }
        if let m = keyMonitor { NSEvent.removeMonitor(m); keyMonitor = nil }
        if let o = popCloseObserver { NotificationCenter.default.removeObserver(o); popCloseObserver = nil }
        if let o = writeBackObserver { NotificationCenter.default.removeObserver(o); writeBackObserver = nil }
    }
}
